export const SCRIPTS: { code: string; exports: string[] }[] = [{"code":"\n/* ── Theme toggle ── */\ndocument.querySelectorAll('.theme-toggle').forEach(btn => {\n  btn.addEventListener('click', () => {\n    const next = document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';\n    document.documentElement.setAttribute('data-theme', next);\n    localStorage.setItem('diraflow-theme', next);\n  });\n});\n\n/* ── Anonymous toggle ── */\nfunction toggleAnonymous(checkbox) {\n  const fields = document.getElementById('identity-fields');\n  const inputs = fields.querySelectorAll('input, select');\n  if (checkbox.checked) {\n    fields.style.opacity = '0.35';\n    fields.style.pointerEvents = 'none';\n    inputs.forEach(i => i.removeAttribute('required'));\n  } else {\n    fields.style.opacity = '1';\n    fields.style.pointerEvents = 'auto';\n  }\n}\n\n/* ── Show/hide preferred contact method ── */\nfunction toggleContactMethod(sel) {\n  const field = document.getElementById('preferred-contact');\n  const show  = sel.value === 'yes_email' || sel.value === 'yes_any';\n  field.style.display = show ? 'block' : 'none';\n}\n\n/* ── Generate reference number ── */\nfunction generateRef() {\n  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';\n  let ref = 'DWB-';\n  for (let i = 0; i < 8; i++) ref += chars[Math.floor(Math.random() * chars.length)];\n  return ref;\n}\n\n/* ── Report form submission ── */\nconst reportForm = document.getElementById('report-form');\nif (reportForm) {\n  reportForm.addEventListener('submit', async e => {\n    e.preventDefault();\n\n    // Validate checkbox\n    const confirm = document.getElementById('confirm-checkbox');\n    if (!confirm.checked) {\n      alert('Please confirm that the information is accurate before submitting.');\n      return;\n    }\n\n    const btn     = document.getElementById('report-submit-btn');\n    const success = document.getElementById('report-success');\n    const error   = document.getElementById('report-error');\n    const refEl   = document.getElementById('report-ref');\n\n    btn.textContent = '🔒 Submitting securely…';\n    btn.disabled    = true;\n    error.style.display = 'none';\n\n    // Add reference number to submission\n    const ref = generateRef();\n    const hiddenRef = document.createElement('input');\n    hiddenRef.type  = 'hidden';\n    hiddenRef.name  = 'reference_number';\n    hiddenRef.value = ref;\n    reportForm.appendChild(hiddenRef);\n\n    try {\n      const res = await fetch(reportForm.action, {\n        method:  'POST',\n        body:    new FormData(reportForm),\n        headers: { 'Accept': 'application/json' }\n      });\n      if (res.ok) {\n        reportForm.querySelectorAll('input, select, textarea, button').forEach(el => el.disabled = true);\n        document.querySelector('.anon-toggle').style.pointerEvents = 'none';\n        btn.style.display     = 'none';\n        refEl.textContent     = ref;\n        success.style.display = 'block';\n        success.scrollIntoView({ behavior: 'smooth', block: 'center' });\n      } else { throw new Error(); }\n    } catch {\n      error.style.display = 'block';\n      btn.textContent     = '🔒 Submit confidential report →';\n      btn.disabled        = false;\n    }\n  });\n}\n","exports":["toggleAnonymous","toggleContactMethod","generateRef"]}];
